using System.Collections.Frozen;

namespace Harborline.Foundation.NotificationDelivery;

/// <summary>
/// A closed transport identifier. Release 1 admits only the on-node inbox
/// (<c>notification-delivery-ck-1</c>).
/// </summary>
public readonly record struct DeliveryChannelKey
{
    private DeliveryChannelKey(string value) => Value = value;

    /// <summary>The recipient's on-node inbox transport.</summary>
    public static DeliveryChannelKey Inbox { get; } = new("inbox");

    /// <summary>The stable transport name.</summary>
    public string Value { get; }

    /// <inheritdoc />
    public override string ToString() => Value ?? string.Empty;
}

/// <summary>The amount of a rendered notification a transport is permitted to carry.</summary>
public enum ChannelContentClass
{
    /// <summary>The on-node transport carries the complete rendered notification.</summary>
    OnNodeFull = 0,
    /// <summary>An off-node transport carries its tier, definition title, subject display name and link only.</summary>
    LinkOnly = 1,
}

/// <summary>
/// Code-registered transport capabilities. Secret requirements and retry profiles are names rather
/// than values, so a binding can never become a credential store.
/// </summary>
public sealed record DeliveryChannel
{
    /// <summary>Registers capabilities and the required transport-result classifier.</summary>
    public DeliveryChannel(
        DeliveryChannelKey key,
        IReadOnlySet<string> requiredSecretReferenceNames,
        IReadOnlySet<string> allowedRetryProfiles,
        ChannelContentClass contentClass,
        Func<DeliveryTransportResult, DeliveryOutcomeClass> classifyResult)
    {
        if (classifyResult is null)
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.ClassificationRequired,
                "A channel must declare its outcome classification.");
        }

        Key = key;
        RequiredSecretReferenceNames = requiredSecretReferenceNames;
        AllowedRetryProfiles = allowedRetryProfiles;
        ContentClass = contentClass;
        _classifyResult = classifyResult;
    }

    private readonly Func<DeliveryTransportResult, DeliveryOutcomeClass> _classifyResult;

    /// <summary>The registered transport identifier.</summary>
    public DeliveryChannelKey Key { get; }
    /// <summary>Secret reference names required by the transport.</summary>
    public IReadOnlySet<string> RequiredSecretReferenceNames { get; }
    /// <summary>Retry profiles admitted by the transport.</summary>
    public IReadOnlySet<string> AllowedRetryProfiles { get; }
    /// <summary>The amount of rendered content admitted by the transport.</summary>
    public ChannelContentClass ContentClass { get; }

    /// <summary>Classifies a transport result, retaining its diagnostic verbatim (notification-delivery-ck-8).</summary>
    public DeliveryOutcome Classify(DeliveryTransportResult result)
    {
        ArgumentNullException.ThrowIfNull(result);
        var classification = _classifyResult(result);
        if (!Enum.IsDefined(classification))
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.OutcomeUnknown,
                "The transport classifier returned an unknown outcome.");
        }

        return new DeliveryOutcome(classification, result.Diagnostic);
    }
}

/// <summary>The closed notification-delivery-ck-8 outcome vocabulary.</summary>
public enum DeliveryOutcomeClass
{
    /// <summary>Handed to a relay without further confirmation.</summary>
    Accepted = 0,
    /// <summary>Committed to the inbox or confirmed by the transport.</summary>
    Delivered = 1,
    /// <summary>A temporary failure eligible for the declared retry profile.</summary>
    Transient = 2,
    /// <summary>A permanent failure that never retries.</summary>
    Permanent = 3,
}

/// <summary>A transport's completion fact and unmodified diagnostic; for the inbox, success means a committed write.</summary>
public sealed record DeliveryTransportResult(bool Succeeded, string Diagnostic);

/// <summary>A classified outcome beside the transport's diagnostic, never parsed by consumers.</summary>
public sealed record DeliveryOutcome(DeliveryOutcomeClass Classification, string Diagnostic);

/// <summary>
/// Tenant configuration for a registered channel. It can identify secrets held by the tenant, but
/// never stores their values (<c>notification-delivery-ck-2</c>).
/// </summary>
public sealed record ChannelBinding
{
    /// <summary>
    /// Creates a binding after ensuring its channel exists and every supplied secret reference is
    /// declared by that channel.
    /// </summary>
    public ChannelBinding(
        string tenant,
        DeliveryChannelKey channel,
        bool enabled,
        string? senderIdentity,
        IReadOnlyList<string> secretReferenceIds)
    {
        ArgumentNullException.ThrowIfNull(secretReferenceIds);
        var registered = DeliveryChannels.Require(channel);
        if (secretReferenceIds.Count != 0 && registered.RequiredSecretReferenceNames.Count == 0)
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.SecretReferenceNotAllowed,
                $"Channel '{channel}' declares no secret references.");
        }

        Tenant = tenant;
        Channel = channel;
        Enabled = enabled;
        SenderIdentity = senderIdentity;
        SecretReferenceIds = secretReferenceIds.ToArray();
    }

    /// <summary>The tenant that owns this non-portable channel configuration.</summary>
    public string Tenant { get; }

    /// <summary>The registered transport this configuration enables or disables.</summary>
    public DeliveryChannelKey Channel { get; }

    /// <summary>Whether the tenant admits this transport for routing.</summary>
    public bool Enabled { get; }

    /// <summary>The transport's configured sender identity, when that transport uses one.</summary>
    public string? SenderIdentity { get; }

    /// <summary>Tenant-held secret reference identifiers; this collection never contains secret values.</summary>
    public IReadOnlyList<string> SecretReferenceIds { get; }
}

/// <summary>Raised when a notification-delivery boundary refuses invalid channel configuration.</summary>
public sealed class NotificationDeliveryRefusedException : InvalidOperationException
{
    /// <summary>Creates a refusal with a stable machine-readable code and an operator-readable explanation.</summary>
    public NotificationDeliveryRefusedException(string code, string message)
        : base(message) => Code = code;

    /// <summary>The stable refusal code.</summary>
    public string Code { get; }
}

/// <summary>Stable refusal codes emitted by the channels slice.</summary>
public static class NotificationDeliveryRefusals
{
    /// <summary>The caller named a transport that this release does not register.</summary>
    public const string ChannelUnknown = "notification_delivery.channel_unknown";

    /// <summary>A channel did not declare an outcome classifier.</summary>
    public const string ClassificationRequired = "notification_delivery.classification_required";

    /// <summary>A classifier returned a value outside the closed outcome vocabulary.</summary>
    public const string OutcomeUnknown = "notification_delivery.outcome_unknown";

    /// <summary>The binding supplied secret references to a transport that declares none.</summary>
    public const string SecretReferenceNotAllowed = "notification_delivery.secret_reference_not_allowed";

    /// <summary>The caller supplied no usable value for an inbox-entry field that the inbox must render.</summary>
    public const string InboxEntryInvalid = "notification_delivery.inbox_entry_invalid";

    /// <summary>The caller tried to update an entry that does not belong to the current person's inbox.</summary>
    public const string InboxEntryUnknown = "notification_delivery.inbox_entry_unknown";
}

/// <summary>The code registry for delivery transports; a new transport registers here, not a second delivery path.</summary>
public static class DeliveryChannels
{
    private static readonly DeliveryChannel Inbox = new(
        DeliveryChannelKey.Inbox,
        Array.Empty<string>().ToFrozenSet(StringComparer.Ordinal),
        Array.Empty<string>().ToFrozenSet(StringComparer.Ordinal),
        ChannelContentClass.OnNodeFull,
        result => result.Succeeded ? DeliveryOutcomeClass.Delivered : DeliveryOutcomeClass.Permanent);

    /// <summary>The mandatory privacy class with which a future off-node channel must begin.</summary>
    public static ChannelContentClass ExternalDefaultContentClass => ChannelContentClass.LinkOnly;

    /// <summary>Returns the registered channel or refuses a channel key unavailable in this release.</summary>
    public static DeliveryChannel Require(DeliveryChannelKey key) =>
        key == DeliveryChannelKey.Inbox
            ? Inbox
            : throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.ChannelUnknown,
                $"Channel '{key}' is not registered.");
}

namespace Harborline.Foundation.NotificationDelivery;

/// <summary>The per-person state of an inbox entry, shared by every device for that person.</summary>
public enum InboxReadState
{
    /// <summary>The recipient has not yet read the entry.</summary>
    Unread = 0,
    /// <summary>The recipient has read the entry.</summary>
    Read = 1,
    /// <summary>The recipient has removed the entry from their active inbox.</summary>
    Dismissed = 2,
}

/// <summary>
/// One durable, on-node notification-centre item. Its rendered content is intentionally retained
/// here rather than projected to an external channel (<c>notification-delivery-ck-10</c>).
/// </summary>
public sealed record InboxEntry(
    Guid Id,
    string Tenant,
    string Recipient,
    string Tier,
    string Title,
    string RenderedContent,
    string SubjectDisplayName,
    string SubjectLink,
    bool AnswerOwed,
    DateTimeOffset CreatedAt,
    InboxReadState ReadState);

/// <summary>The caller-provided content for one inbox write.</summary>
public sealed record WriteInboxEntry(
    string Tenant,
    string Recipient,
    string Tier,
    string Title,
    string RenderedContent,
    string SubjectDisplayName,
    string SubjectLink,
    bool AnswerOwed);

/// <summary>Tenant- and recipient-scoped inbox persistence and read-state operations.</summary>
public interface IInboxStore
{
    /// <summary>Appends the delivered entry before it becomes visible to the recipient.</summary>
    Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default);

    /// <summary>Lists one recipient's entries newest first for the notification-centre surface.</summary>
    Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default);

    /// <summary>Counts unread entries for the same recipient the notification centre displays.</summary>
    Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default);

    /// <summary>Marks one entry read for every session belonging to its recipient.</summary>
    Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default);

    /// <summary>Dismisses one delivery for its tenant and recipient; an entry outside that scope refuses.</summary>
    Task DismissAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default);

    /// <summary>Marks every unread entry read for the recipient's notification centre.</summary>
    Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default);
}

/// <summary>In-process atomic inbox persistence suitable for development composition and focused tests.</summary>
public sealed class InMemoryInboxStore : IInboxStore
{
    private readonly object _gate = new();
    private readonly Dictionary<Guid, InboxEntry> _entries = [];

    /// <inheritdoc />
    public Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entry);
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            _entries.Add(entry.Id, entry);
            return Task.FromResult(entry);
        }
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<InboxEntry> entries = _entries.Values
                .Where(entry => entry.Tenant == tenant && entry.Recipient == recipient)
                .OrderByDescending(entry => entry.CreatedAt)
                .ThenBy(entry => entry.Id)
                .ToArray();
            return Task.FromResult(entries);
        }
    }

    /// <inheritdoc />
    public Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            return Task.FromResult(_entries.Values.Count(entry => entry.Tenant == tenant
                && entry.Recipient == recipient
                && entry.ReadState == InboxReadState.Unread));
        }
    }

    /// <inheritdoc />
    public Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            if (!_entries.TryGetValue(entryId, out var entry) || entry.Tenant != tenant || entry.Recipient != recipient)
            {
                throw new NotificationDeliveryRefusedException(
                    NotificationDeliveryRefusals.InboxEntryUnknown,
                    $"Inbox entry '{entryId}' is not in this recipient's inbox.");
            }

            if (entry.ReadState == InboxReadState.Unread)
            {
                _entries[entryId] = entry with { ReadState = InboxReadState.Read };
            }
            return Task.CompletedTask;
        }
    }

    /// <inheritdoc />
    public Task DismissAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            if (!_entries.TryGetValue(entryId, out var entry) || entry.Tenant != tenant || entry.Recipient != recipient)
            {
                throw new NotificationDeliveryRefusedException(
                    NotificationDeliveryRefusals.InboxEntryUnknown,
                    $"Inbox entry '{entryId}' is not in this recipient's inbox.");
            }

            _entries[entryId] = entry with { ReadState = InboxReadState.Dismissed };
            return Task.CompletedTask;
        }
    }

    /// <inheritdoc />
    public Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            foreach (var entry in _entries.Values.Where(entry => entry.Tenant == tenant
                && entry.Recipient == recipient
                && entry.ReadState == InboxReadState.Unread).ToArray())
            {
                _entries[entry.Id] = entry with { ReadState = InboxReadState.Read };
            }

            return Task.CompletedTask;
        }
    }
}

/// <summary>The in-app delivery channel that writes complete rendered content to the person's on-node inbox.</summary>
public sealed class InboxChannel
{
    private readonly IInboxStore _store;
    private readonly TimeProvider _clock;

    /// <summary>Creates the channel with its durable inbox boundary and the authoritative time source.</summary>
    public InboxChannel(IInboxStore store, TimeProvider clock)
    {
        _store = store ?? throw new ArgumentNullException(nameof(store));
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    }

    /// <summary>Writes one unread inbox entry with the full rendered content and returns the committed item.</summary>
    public async Task<InboxEntry> WriteAsync(WriteInboxEntry request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        RequireContent(request.Tenant, nameof(request.Tenant));
        RequireContent(request.Recipient, nameof(request.Recipient));
        RequireContent(request.Tier, nameof(request.Tier));
        RequireContent(request.Title, nameof(request.Title));
        RequireContent(request.RenderedContent, nameof(request.RenderedContent));
        RequireContent(request.SubjectDisplayName, nameof(request.SubjectDisplayName));
        RequireContent(request.SubjectLink, nameof(request.SubjectLink));
        var entry = new InboxEntry(
            Guid.NewGuid(),
            request.Tenant,
            request.Recipient,
            request.Tier,
            request.Title,
            request.RenderedContent,
            request.SubjectDisplayName,
            request.SubjectLink,
            request.AnswerOwed,
            _clock.GetUtcNow(),
            InboxReadState.Unread);
        return await _store.AppendAsync(entry, cancellationToken).ConfigureAwait(false);
    }

    private static void RequireContent(string value, string parameterName)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new NotificationDeliveryRefusedException(
                NotificationDeliveryRefusals.InboxEntryInvalid,
                $"Inbox entry field '{parameterName}' is required.");
        }
    }
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class ClassificationAndDismissTests
{
    // Oracle: DES-0055 ck-8's exhaustive four-member vocabulary (control #1263).
    // Mutation outcome-added: add Unexpected = 4 to DeliveryOutcomeClass.
    [Fact(DisplayName = "notification-delivery-ck-8: outcome vocabulary is closed")]
    public void Outcome_vocabulary_is_closed()
    {
        Assert.Equal(new[] { "Accepted", "Delivered", "Transient", "Permanent" }, Enum.GetNames<DeliveryOutcomeClass>());
        Assert.Equal(new[] { 0, 1, 2, 3 }, Enum.GetValues<DeliveryOutcomeClass>().Select(value => (int)value));
    }

    // Oracle: ck-1 requires a classifier; no unset capability is admitted (control #1263).
    // Mutation classifier-unset: replace `classifyResult is null` with false.
    [Fact(DisplayName = "notification-delivery-ck-1: unset outcome classification refuses")]
    public void Unset_classifier_refuses()
    {
        var refusal = Assert.Throws<NotificationDeliveryRefusedException>(() => Channel(null!));
        Assert.Equal("notification_delivery.classification_required", refusal.Code);
        Assert.Equal("A channel must declare its outcome classification.", refusal.Message);
    }

    // Oracle: ck-8 requires diagnostic preservation, regardless of the declared mapping.
    // Mutation diagnostic-replaced: return an empty diagnostic from Classify.
    [Theory(DisplayName = "notification-delivery-ck-1 notification-delivery-ck-8: declared classifier preserves diagnostic verbatim")]
    [InlineData(DeliveryOutcomeClass.Accepted)]
    [InlineData(DeliveryOutcomeClass.Delivered)]
    [InlineData(DeliveryOutcomeClass.Transient)]
    [InlineData(DeliveryOutcomeClass.Permanent)]
    public void Declared_classifier_preserves_diagnostic(DeliveryOutcomeClass expected)
    {
        var result = new DeliveryTransportResult(false, "  550\r\n opaque: Ä; do not parse  ");
        DeliveryTransportResult? seen = null;
        var channel = Channel(value => { seen = value; return expected; });
        var outcome = channel.Classify(result);
        Assert.Same(result, seen);
        Assert.Equal(expected, outcome.Classification);
        Assert.Equal("  550\r\n opaque: Ä; do not parse  ", outcome.Diagnostic);
        Assert.Equal(DeliveryChannelKey.Inbox, channel.Key);
        Assert.Equal(new[] { "credential" }, channel.RequiredSecretReferenceNames);
        Assert.Equal(new[] { "retry" }, channel.AllowedRetryProfiles);
        Assert.Equal(ChannelContentClass.LinkOnly, channel.ContentClass);
    }

    // Oracle: only the four ck-8 classes may cross the boundary.
    // Mutation unknown-admitted: replace !Enum.IsDefined(classification) with false.
    [Fact(DisplayName = "notification-delivery-ck-8: undefined classifier outcome refuses")]
    public void Undefined_outcome_refuses()
    {
        var refusal = Assert.Throws<NotificationDeliveryRefusedException>(() =>
            Channel(_ => (DeliveryOutcomeClass)99).Classify(new(false, "opaque")));
        Assert.Equal("notification_delivery.outcome_unknown", refusal.Code);
        Assert.Equal("The transport classifier returned an unknown outcome.", refusal.Message);
        Assert.Throws<ArgumentNullException>(() => Channel(_ => DeliveryOutcomeClass.Delivered).Classify(null!));
    }

    // Oracle: control #1263 / DES-0055 ruling 7: committed = delivered, failed = permanent.
    // This exercises the declared mapping. The test adapts write completion into a transport result;
    // production write-to-result orchestration belongs to the later delivery-attempt slice.
    // Mutation inbox-inverted: negate result.Succeeded in the inbox classifier.
    [Theory(DisplayName = "notification-delivery-ck-1 notification-delivery-ck-8: inbox classifies committed and failed writes without retry")]
    [InlineData(false, DeliveryOutcomeClass.Delivered)]
    [InlineData(true, DeliveryOutcomeClass.Permanent)]
    public async Task Inbox_classifies_write_completion(bool fail, DeliveryOutcomeClass expected)
    {
        IInboxStore store = fail ? new FailingStore() : new InMemoryInboxStore();
        var writer = new InboxChannel(store, TimeProvider.System);
        DeliveryTransportResult result;
        try
        {
            var entry = await writer.WriteAsync(new("tenant-a", "person-a", "information", "Title", "Body", "Subject", "/subject", false));
            Assert.Single(await store.ListAsync("tenant-a", "person-a"));
            Assert.Equal(InboxReadState.Unread, entry.ReadState);
            result = new(true, "committed verbatim");
        }
        catch (InvalidOperationException exception)
        {
            result = new(false, exception.Message);
        }
        var channel = DeliveryChannels.Require(DeliveryChannelKey.Inbox);
        var outcome = channel.Classify(result);
        Assert.Equal(expected, outcome.Classification);
        Assert.Equal(fail ? "store defect verbatim\r\n" : "committed verbatim", outcome.Diagnostic);
        Assert.Empty(channel.AllowedRetryProfiles);
    }

    // Oracle: ck-7 is per delivery, not per recipient or tenant; dismissal clears unread count.
    // Mutation dismiss-read: write Read rather than Dismissed in DismissAsync.
    // Mutation mark-read-undismiss: remove the unread-only guard in MarkReadAsync.
    [Fact(DisplayName = "notification-delivery-ck-7: dismiss changes only one scoped delivery")]
    public async Task Dismiss_changes_only_one_delivery()
    {
        IInboxStore store = new InMemoryInboxStore();
        var target = Entry("tenant-a", "person-a");
        var other = Entry("tenant-a", "person-a");
        var otherPerson = Entry("tenant-a", "person-b");
        var otherTenant = Entry("tenant-b", "person-a");
        foreach (var entry in new[] { target, other, otherPerson, otherTenant }) await store.AppendAsync(entry);
        await store.DismissAsync("tenant-a", "person-a", target.Id);
        await store.DismissAsync("tenant-a", "person-a", target.Id); // idempotent
        await store.MarkReadAsync("tenant-a", "person-a", target.Id); // a late read must not undo dismissal
        var listed = await store.ListAsync("tenant-a", "person-a");
        Assert.Equal(InboxReadState.Dismissed, listed.Single(entry => entry.Id == target.Id).ReadState);
        Assert.Equal(InboxReadState.Unread, listed.Single(entry => entry.Id == other.Id).ReadState);
        Assert.Equal(1, await store.UnreadCountAsync("tenant-a", "person-a"));
        Assert.Equal(otherPerson, Assert.Single(await store.ListAsync("tenant-a", "person-b")));
        Assert.Equal(otherTenant, Assert.Single(await store.ListAsync("tenant-b", "person-a")));
        await store.MarkAllReadAsync("tenant-a", "person-a");
        Assert.Equal(InboxReadState.Dismissed, (await store.ListAsync("tenant-a", "person-a")).Single(entry => entry.Id == target.Id).ReadState);
    }

    // Oracle: ck-7 / ck-10 tenant data belongs to one person; wrong scope and absent ids refuse identically.
    // Mutations dismiss-tenant / dismiss-recipient: remove the corresponding scope predicate.
    [Theory(DisplayName = "notification-delivery-ck-7: dismissal refuses unknown and foreign deliveries")]
    [InlineData("tenant-b", "person-a", false)]
    [InlineData("tenant-a", "person-b", false)]
    [InlineData("tenant-a", "person-a", true)]
    public async Task Dismiss_refuses_foreign_or_unknown(string tenant, string recipient, bool missing)
    {
        IInboxStore store = new InMemoryInboxStore();
        var entry = Entry("tenant-a", "person-a");
        await store.AppendAsync(entry);
        var id = missing ? Guid.NewGuid() : entry.Id;
        var refusal = await Assert.ThrowsAsync<NotificationDeliveryRefusedException>(() => store.DismissAsync(tenant, recipient, id));
        Assert.Equal("notification_delivery.inbox_entry_unknown", refusal.Code);
        Assert.Equal($"Inbox entry '{id}' is not in this recipient's inbox.", refusal.Message);
        Assert.Equal(entry, Assert.Single(await store.ListAsync("tenant-a", "person-a")));
    }

    // Oracle: IInboxStore's cancellation contract prevents a cancelled mutation.
    // Mutation dismiss-cancellation: remove ThrowIfCancellationRequested in DismissAsync.
    [Fact(DisplayName = "notification-delivery-ck-7: cancelled dismissal leaves delivery unchanged")]
    public async Task Cancelled_dismissal_leaves_delivery_unchanged()
    {
        IInboxStore store = new InMemoryInboxStore();
        var entry = Entry("tenant-a", "person-a");
        await store.AppendAsync(entry);
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        var refusal = await Assert.ThrowsAsync<OperationCanceledException>(() => store.DismissAsync("tenant-a", "person-a", entry.Id, cancellation.Token));
        Assert.Equal(cancellation.Token, refusal.CancellationToken);
        Assert.Equal(entry, Assert.Single(await store.ListAsync("tenant-a", "person-a")));
    }

    private static DeliveryChannel Channel(Func<DeliveryTransportResult, DeliveryOutcomeClass> classifier) =>
        new(DeliveryChannelKey.Inbox, new HashSet<string> { "credential" }, new HashSet<string> { "retry" }, ChannelContentClass.LinkOnly, classifier);

    private static InboxEntry Entry(string tenant, string recipient) => new(Guid.NewGuid(), tenant, recipient,
        "information", "Title", "Body", "Subject", "/subject", false, DateTimeOffset.UnixEpoch, InboxReadState.Unread);

    private sealed class FailingStore : IInboxStore
    {
        public Task<InboxEntry> AppendAsync(InboxEntry entry, CancellationToken cancellationToken = default) => throw new InvalidOperationException("store defect verbatim\r\n");
        public Task<IReadOnlyList<InboxEntry>> ListAsync(string tenant, string recipient, CancellationToken cancellationToken = default) => throw new NotSupportedException();
        public Task<int> UnreadCountAsync(string tenant, string recipient, CancellationToken cancellationToken = default) => throw new NotSupportedException();
        public Task MarkReadAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default) => throw new NotSupportedException();
        public Task DismissAsync(string tenant, string recipient, Guid entryId, CancellationToken cancellationToken = default) => throw new NotSupportedException();
        public Task MarkAllReadAsync(string tenant, string recipient, CancellationToken cancellationToken = default) => throw new NotSupportedException();
    }
}

using Harborline.Foundation.NotificationDelivery;
using Xunit;

namespace Harborline.Foundation.NotificationDelivery.Tests;

public sealed class DeliveryChannelBoundaryTests
{
    // DES-0055 notification-delivery-ck-1: the R1 transport key is literally "inbox".
    [Fact(DisplayName = "notification-delivery-ck-1: inbox key renders its stable name and default renders empty")]
    public void Notification_delivery_ck_1_inbox_key_renders_its_stable_name_and_default_renders_empty()
    {
        Assert.Equal("inbox", DeliveryChannelKey.Inbox.Value);
        Assert.Equal("inbox", DeliveryChannelKey.Inbox.ToString());
        Assert.Null(default(DeliveryChannelKey).Value);
        Assert.Equal(string.Empty, default(DeliveryChannelKey).ToString());
    }

    [Fact(DisplayName = "notification-delivery-ck-1: unknown channel refuses with a code and operator explanation")]
    public void Notification_delivery_ck_1_unknown_channel_refuses_with_a_code_and_operator_explanation()
    {
        var exception = Assert.Throws<NotificationDeliveryRefusedException>(() => DeliveryChannels.Require(default));

        Assert.Equal("notification_delivery.channel_unknown", exception.Code);
        Assert.Equal("Channel '' is not registered.", exception.Message);
    }

    // DES-0055 notification-delivery-ck-2: empty secret references are valid for an inbox binding.
    [Theory(DisplayName = "notification-delivery-ck-2: empty binding preserves tenant channel enablement and sender")]
    [InlineData(true, "notification-sender")]
    [InlineData(false, null)]
    public void Notification_delivery_ck_2_empty_binding_preserves_tenant_channel_enablement_and_sender(
        bool enabled, string? senderIdentity)
    {
